apt install -y php-fpm && cat > /etc/nginx/sites-available/php << 'EOF'
server {
  listen 80;
  root /var/www/html;
  index index.php;
  location ~ \.php$ {
    fastcgi_pass unix:/var/run/php/php8.2-fpm.sock;
    include fastcgi_params;
    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
  }
}
EOF && ln -sf /etc/nginx/sites-available/php /etc/nginx/sites-enabled/ && nginx -s reload

echo -e 'function greeting(req) {
  return "Hello from njs!";
}
export default {greeting};' > /etc/nginx/script.js

echo -e 'location /auth {
  proxy_pass http://auth-service;
  proxy_pass_request_body off;
  proxy_set_header Content-Length "";
}
location /protected {
  auth_request /auth;
  proxy_pass http://backend;
}' >> /etc/nginx/sites-available/default && nginx -s reload
